INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 31, 'theory', 'Quiz: metaclasses and __init_subclass__');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 0, 'What is type(int) equal to?', '["int", "object", "type", "class"]', 2, 'The class int is an object, and it is created by type: the "class of classes"; type(type) is type as well.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 1, 'What does the call type(''P'', (), {}) do?', '["Returns the type of a value", "Creates a new class named P with no parents and no attributes", "Creates an instance of the class P", "Raises an error"]', 1, 'With three arguments type creates a class: a name, a tuple of parents, and a dictionary of attributes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 2, 'What runs first: the class''s __new__ or the metaclass''s __call__?', '["The class''s __new__", "Their order is random", "The metaclass''s __call__: it is what calls __new__ and __init__", "The class''s __init__"]', 2, 'A() calls type(A).__call__, and that in turn runs A.__new__ and A.__init__ one after the other.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 3, 'When is the parent''s __init_subclass__ called?', '["When an instance of a descendant is created", "On every call of a descendant''s method", "When the parent is imported", "When each new descendant class is defined"]', 3, 'The hook fires once per descendant at the moment the class is created, and it receives the keyword arguments from the class statement.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 4, 'What is the better choice if you just need to register all descendants of a base class?', '["A metaclass", "The __init_subclass__ hook", "Replacing type", "Copying classes by hand"]', 1, 'The hook is simpler than a metaclass: no new class is needed and there are no metaclass conflicts.');
